//! Bitmap glyphs, baked in.
//!
//! GENERATED BY tools/mkfont.py -- do not edit by hand.
//!
//! A node has no font package, no fontconfig and no internet, so the
//! console carries its letters with it. That is not a compromise here:
//! a fixed bitmap font at a fixed size is exactly what a wall of small
//! labels wants, and it renders identically on every machine rather
//! than depending on what happens to be installed.
//!
//! Source: the X.Org "misc-fixed" fonts, whose own COPYRIGHT property
//! is reproduced for each face below.
//!
//!   8x13   8x13  Fixed
//!            Public domain font.  Share and enjoy.
//!
//!   10x20  10x20  Fixed
//!            Public domain font.  Share and enjoy.

/// One face: a dense block for 32..=255, then EXTRAS in order.
pub struct Font {
    pub width: usize,
    pub height: usize,
    /// Rows from the top. Bit 0 is the leftmost pixel.
    pub glyphs: &'static [[u16; 20]],
    pub first: u8,
}

/// The code points baked past Latin-1, in the order they are stored.
///
/// U+2190 and U+2014 were added when the file browser drew a button labelled
/// "← copy" and the arrow came out as a blank cell -- `glyph` refuses to panic
/// on an unbaked character, which is right, and means a missing glyph is
/// silent. IF A DRAWN STRING USES A CHARACTER, IT BELONGS ON THIS LIST; the
/// test at the bottom of this file is what makes that true rather than hoped.
pub static EXTRAS: [u32; 7] = [0x2026, 0x2192, 0x25cf, 0x25cb, 0x2580, 0x2190, 0x2014];

impl Font {
    /// The rows for one character, or the blank cell for anything
    /// outside the baked range -- a console must not panic on a stray
    /// byte from a node's own output.
    pub fn glyph(&self, c: char) -> &'static [u16] {
        let u = c as u32;
        if u >= self.first as u32 && u <= 255 {
            let row = &self.glyphs[(u - self.first as u32) as usize];
            return &row[..self.height];
        }
        // A handful of characters live past the dense block. The scan is
        // over five entries and only runs for non-Latin-1 text.
        let dense = (255 - self.first as u32 + 1) as usize;
        if let Some(i) = EXTRAS.iter().position(|e| *e == u) {
            let row = &self.glyphs[dense + i];
            return &row[..self.height];
        }
        &BLANK[..self.height]
    }

    pub fn advance(&self) -> usize {
        self.width
    }

    /// How wide `s` will be, in pixels.
    pub fn measure(&self, s: &str) -> usize {
        s.chars().count() * self.width
    }
}

static BLANK: [u16; 20] = [0; 20];

